from typing import Any


class ConfigError(Exception):
    """Raised when an environment variable is malformed or refers to an unknown key."""
    pass


def _coerce(value: str, expected_type: type) -> Any:
    """Coerce a string to the expected type. Raises ConfigError on failure."""
    if expected_type is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError(f"Invalid integer for key: {value}")
    if expected_type is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError(f"Invalid float for key: {value}")
    if expected_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ConfigError(f"Invalid boolean for key: {value}")
    if expected_type is str:
        return value
    raise ConfigError(f"Unsupported type for coercion: {expected_type}")


def _merge_dicts(base: dict, override: dict) -> dict:
    """Recursively merge override into base, returning a new dict."""
    result = dict(base)
    for key, val in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(val, dict):
            result[key] = _merge_dicts(result[key], val)
        else:
            result[key] = val
    return result


