import os
import tempfile
import pytest
from envcfg import load_config, ConfigError


def _write_toml(path: str, data: dict) -> None:
    import tomllib
    import tomli_w
    tomli_w.dump(data, open(path, "wb"))


def _read_toml(path: str) -> dict:
    with open(path, "rb") as f:
        return tomllib.load(f)


class TestDefaults:
    def test_defaults_only(self):
        cfg = load_config({"a": 1, "b": 2})
        assert cfg == {"a": 1, "b": 2}


class TestTOML:
    def test_toml_overrides_defaults(self, tmp_path):
        toml_path = tmp_path / "cfg.toml"
        _write_toml(str(toml_path), {"a": 10, "b": 20})
        cfg = load_config({"a": 1, "b": 2}, toml_path=str(toml_path))
        assert cfg == {"a": 10, "b": 20}

    def test_missing_toml_file(self, tmp_path):
        cfg = load_config({"a": 1}, toml_path=str(tmp_path / "missing.toml"))
        assert cfg == {"a": 1}

    def test_nested_toml(self, tmp_path):
        toml_path = tmp_path / "cfg.toml"
        _write_toml(str(toml_path), {"server": {"port": 8080, "timeout": 30}})
        cfg = load_config({"server": {"port": 80}}, toml_path=str(toml_path))
        assert cfg == {"server": {"port": 8080, "timeout": 30}}


class TestEnvVars:
    def test_env_overrides_defaults(self):
        env = {"APP__A": "100"}
        cfg = load_config({"a": 1}, env=env)
        assert cfg == {"a": 100}

    def test_env_overrides_toml(self, tmp_path):
        toml_path = tmp_path / "cfg.toml"
        _write_toml(str(toml_path), {"a": 10})
        env = {"APP__A": "200"}
        cfg = load_config({"a": 1}, toml_path=str(toml_path), env=env)
        assert cfg == {"a": 200}

    def test_nested_env(self):
        env = {"APP__SERVER__PORT": "9000"}
        cfg = load_config({"server": {"port": 80}}, env=env)
        assert cfg == {"server": {"port": 9000}}

    def test_custom_prefix(self):
        env = {"MYAPP__A": "100"}
        cfg = load_config({"a": 1}, env_prefix="MYAPP", env=env)
        assert cfg == {"a": 100}

